Lemma chkT fx R M cur k :
  getr R (reg 10) = Z_to_bv 64 cur -> getr R (reg 12) = Z_to_bv 64 (cur / 8 + SBL) -> 0 <= cur < 2 ^ 47 ->
  rdn RSEGS M (Z_to_bv 64 (cur / 8 + SBL)) 1%nat = Some [Z_to_bv 8 k] ->
  (k = 0 \/ (1 <= k <= 7 /\ cur mod 8 < k)) ->
  exists R', msteps RSEGS (mst fx R 0xc7714 M) (mst fx R' 0xc771c M)
    /\ (forall j, j <> 12%nat -> j <> 14%nat -> (j < 32)%nat -> getr R' (reg j) = getr R (reg j)).
Proof.
