Hypothesis FAMok : HAR.asan_famR_ok L ar C SCFG LR HIk.
Let LYa := PMA.ly_as0 L C LY.
Let HIokF (D0 : list (list Z)) : HAJ.asan_iface_okR L ar C SCFG (HIk D0) := HAR.fr_base L ar C SCFG LR HIk FAMok D0.
