Lemma sbyte D LB FF LK cr Aw (M : mem) model s n :
  ri_inv (HIk D) LB FF LK cr Aw M (vml_of model) -> 0 < n -> 0 <= s -> s + n <= 2 ^ 47 -> L5.defined M s n -> PMSPA.accA M s n ->
  (n = 0 \/ PGS.in_blk LB s n \/ PMSPA.aobjA FF s n) ->
  let MV := mrestrict (ahid Aw model) M in
  (exists b, L5.u8_at RSEGS MV s b /\ 0 <= b < 256)
  /\ (exists kk, rdn RSEGS MV (Z_to_bv 64 (s / 8 + SBL)) 1%nat = Some [Z_to_bv 8 kk] /\ (kk = 0 \/ (1 <= kk <= 7 /\ s mod 8 < kk)))
  /\ 4096 <= s.
