(* [comment removed for export] *)
Lemma rchain16 (M M1 : mem) sp fp0 RC :
  HAR.rchain L ar M sp fp0 RC -> sp + 16 <= fp0 -> 32 <= sp -> sp mod 16 = 0 -> ar_stack_top ar < 2 ^ 64 ->
  (forall x : word, sp <= bv_unsigned x < ar_stack_top ar -> M1 x = M x) ->
  HAR.rchain L ar M1 (sp - 16) fp0 RC.
