(* [comment removed for export] *)
Lemma blk_facts (p : Z) : ablock_range L ar p 64 ->
  4096 <= p /\ p + 64 <= ahl_ceil ar /\ p mod 16 = 0 /\ p mod 8 = 0 /\ (2147446784 + 17592186048512 <= p \/ p + 64 <= 2147446784)
  /\ (forall j, 0 <= j < 8 -> 2147446784 <= p / 8 + 2147450880 + j /\ p / 8 + 2147450880 + j + 1 <= 2147446784 + 17592186048512)
  /\ (p + 64 - 1) / 8 = p / 8 + 7.
Proof.
