Lemma RCALL (gk : list Z) (p lo hi : Z) M6 model6 LK6 Aw6 cr6 (fx6 : FPState) R6 :
  In gk GKEYS -> GM [gk :: D] [(p, 64)] M6 model6 LK6 Aw6 cr6 ->
  ablock_range L ar p 64 -> blocks_apart p 64 LBX -> fframes_apart p 64 (FF' ++ LK6) -> L5.defined M6 p 64 -> shadow_blk M6 p 64 ->
  PMSP.credit_keep cr cr6 (PQATSG.gcostD L gk D 64) PMSP.cr0 ->
  L5.big_at RSEGS M6 o (L5.BO (Z.lor fb 1) 3%nat (L5.BDyn 8 p)) ->
  L5.u64_at RSEGS M6 p lo -> L5.u64_at RSEGS M6 (p + 8) hi -> L5.u64_at RSEGS M6 (p + 16) 0 -> 0 <= lo < 2 ^ 64 -> lo + 2 ^ 64 * hi = v0 + 2 ^ 64 * v1 + y ->
  getr R6 (reg 1) = Z_to_bv 64 RA_RD -> getr R6 (reg 10) = Z_to_bv 64 o ->
  getr R6 (reg 2) = Z_to_bv 64 spc -> getr R6 (reg 3) = getr R (reg 3) -> getr R6 (reg 4) = getr R (reg 4) -> getr R6 (reg 27) = getr R (reg 27) ->
  getr R6 (reg 8) = Z_to_bv 64 sp -> getr R6 (reg 18) = Z_to_bv 64 F -> getr R6 (reg 19) = Z_to_bv 64 o -> getr R6 (reg 22) = Z_to_bv 64 (F / 8 + 2147450880) ->
  getr R6 (reg 23) = Z_to_bv 64 F ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx6 R6 RDPC M6 model6) K.
Proof.
