(* [comment removed for export] *)
Section Frame.
Variables (F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model).
Hypothesis G : PQAKUF.gctx L ar HIk D LBX FF LK Aw sp SCR spc (sp - 96) sp OC OWN F fl 1 LK2 M2 model2 cr BX0.
Hypothesis APART : forall a n0 sp0 scr0, (forall i0, 0 <= i0 < n0 -> aclient L ar (BX0 ++ LBX) FF sp0 scr0 (a + i0)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes 1 <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes 1 / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a).
Local Notation FF' := ((F, 1, spc + 32) :: FF).
Local Notation "'GM' [ D1 ]" := (PQAKR3F.g_mem L ar HIk D1 M model LBX FF LK Aw sp PQATSS2.ADD2_H W spc OWN 1 F) (at level 10, D1 at level 200, only parsing).
Local Notation "'GF' [ D1 , INC ] f" := (f L ar C LR HIk D D1 LY FAMok INC K R M model LBX FF LK Aw cr sp r PQATSS2.ADD2_H BX0 W HH AM K0 ENT FRM FRS Hh2 wappW spc (sp - 96) sp OC OWN 1 F fl LK2 M2 model2 G APART HSPCf) (at level 10, D1 at level 200, INC at level 200, f at level 9, only parsing).
Let INC0 : incl D D := incl_refl D.

Ltac pf D1 INC BIx :=
  destruct ((GF [D1, INC] PQAKR3F.g_pfacts) _ _ _ _ _ _ BIx) as ((PF1 & PF2 & PF3 & PF4 & _) & (FD & FW & FSW & FLU & FLW) & (PL1 & PL2 & PL3 & PL4) & (SW & OWNV & PS1 & PS2 & PS3 & PS4) & (CSB & CUAR & IMGC) & (AVSH & AVF & AVS));
  change (ff_bytes 1) with 128 in *; change (128 / 8) with 16 in *.

