Let LYa := PMA.ly_as0 L C LY.
Let HIokF (D : list (list Z)) : HAJ.asan_iface_okR L ar C SCFG (HIk D) := HAR.fr_base L ar C SCFG LR HIk FAMok D.
Let RZ3 := PQATRZ3.resize3_ok L ar C LR HIk LY FAMok.

