(* [comment removed for export] *)
Section Run.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (sp r o fb v0 v1 : Z) (D : list (list Z)).
Local Notation W0 := ([(o, 32)] : list L5.range).
Local Notation SCR := (PMSPA.pm_scr NETSA.MUL10_H).
Local Notation SCR3 := (PMSPA.pm_scr 3).
Local Notation SCR4 := (PMSPA.pm_scr PQATSG.RZ3_H).
Local Notation spc := (sp - 64).
Local Notation VV := (v0 + 2 ^ 64 * v1).
Local Notation GKEYS := (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A).
Let HID := HIk D.
Let HIokD : HAJ.asan_iface_okR L ar C SCFG HID := HIokF D.
Hypothesis HH : ri_inv HID LB FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSPA.entryA AD L ar R M sp r NETSA.MUL10_H.
Hypothesis FRM : PGSA.ffroomB PQRA.FCM NETSA.MUL10_H FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis SP16 : sp mod 16 = 0.
Hypothesis A10 : getr R (reg 10) = Z_to_bv 64 o.
Hypothesis A11 : getr R (reg 11) = Z_to_bv 64 10.
Hypothesis AO : PMSPA.aobjA FF o 32.
Hypothesis O8 : o mod 8 = 0.
Hypothesis ACC : PMSPA.accA M o 32.
Hypothesis BIN : PQATSS.binl_at RSEGS M o fb 2%nat v0 v1.
Hypothesis Tb1 : Z.testbit fb 1 = false.
Hypothesis V1 : 1 <= v1.
Hypothesis BND : 10 * VV < 2 ^ 128.
Hypothesis BASE : PMSTA.base_okA RSEGS AD M.
Hypothesis CR : PQATSG.gpre L LR PQATSG.OPNEW_RA_A D 64 cr.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (cr' : credit) (p w0 w1 : Z) (gk : list Z),
    regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 o -> In gk GKEYS ->
    w0 + 2 ^ 64 * w1 = 10 * VV -> PQATSW2.bdyn_at RSEGS M' o (Z.lor fb 1) 2%nat p w0 w1 ->
    L5CA.afresh L ar LB (FF ++ LK') M' p 64 ->
    L5CA.ahpres L ar LB FF sp SCR W0 M M' ->
    PMSP.credit_keep cr cr' (PQATSG.gcostD L gk D 64) PMSP.cr0 ->
    model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
    ri_inv (HIk (gk :: D)) ((p, 64) :: LB) FF LK' cr' Aw' M' (vml_of model') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

(* [comment removed for export] *)
Definition saves (Mx : mem) : Prop :=
  L5.u64_at RSEGS Mx (sp - 8) r /\ L5.u64_at RSEGS Mx (sp - 16) (bvu (getr R (reg 8))) /\ L5.u64_at RSEGS Mx (sp - 24) (bvu (getr R (reg 9)))
  /\ L5.u64_at RSEGS Mx (sp - 32) (bvu (getr R (reg 18))) /\ L5.u64_at RSEGS Mx (sp - 40) (bvu (getr R (reg 19)))
  /\ L5.u64_at RSEGS Mx (sp - 48) (bvu (getr R (reg 20))) /\ L5.u64_at RSEGS Mx (sp - 56) (bvu (getr R (reg 21))).
(* [comment removed for export] *)
Definition mm0 (M1 : mem) (model1 : Model) (LK1 : list fframe) : Prop :=
  ri_inv HID LB FF LK1 cr Aw M1 (vml_of model1) /\ L5CA.amodel_ok Aw model1 /\ model_rt model model1 /\ incl LK1 LK
  /\ L5SAR.ek L ar LB FF sp SCR W0 M M1 /\ L5SAR.dk L ar LB FF sp SCR M M1 /\ L5CA.astk ar M1 sp SCR /\ saves M1.

