Lemma FIN M4 model4 LK4 (fx4 : FPState) (R4 : bvmap 5 word) (w0 w1 : Z) :
  mm M4 model4 LK4 -> hdr M4 2%nat -> blk M4 w0 w1 0 -> 0 <= w0 < 2 ^ 64 -> 0 <= w1 < 2 ^ 64 -> w0 + 2 ^ 64 * w1 = 10 * VV ->
  getr R4 (reg 2) = Z_to_bv 64 spc -> getr R4 (reg 8) = Z_to_bv 64 o ->
  (forall k, In k [3; 4; 22; 23; 24; 25; 26; 27]%nat -> getr R4 (reg k) = getr R (reg k)) ->
