Lemma FIN (gk : list Z) (p lo hi fbt : Z) M6 model6 LK6 Aw6 cr6 (fx6 : FPState) R6 :
  In gk GKEYS -> GM [gk :: D] [(p, 64)] M6 model6 LK6 Aw6 cr6 ->
  ablock_range L ar p 64 -> blocks_apart p 64 LBX -> fframes_apart p 64 (FF' ++ LK6) -> L5.defined M6 p 64 -> shadow_blk M6 p 64 ->
  PMSP.credit_keep cr cr6 (PQATSG.gcostD L gk D 64) PMSP.cr0 ->
  PQATSG.ws_this_atA RSEGS M6 o (PQATSG.WDyn (Z.lor fbx 1) p lo hi) -> lo + 2 ^ 64 * hi = x0 + 2 ^ 64 * x1 + y0 ->
  L5.u8_at RSEGS M6 (F + 32) fbt -> 0 <= fbt < 256 -> Z.testbit fbt 0 = false ->
  getr R6 (reg 2) = Z_to_bv 64 spc -> getr R6 (reg 3) = getr R (reg 3) -> getr R6 (reg 4) = getr R (reg 4) -> getr R6 (reg 27) = getr R (reg 27) ->
  getr R6 (reg 8) = Z_to_bv 64 sp -> getr R6 (reg 10) = Z_to_bv 64 o -> getr R6 (reg 18) = Z_to_bv 64 F -> getr R6 (reg 21) = Z_to_bv 64 (F + 32) ->
  getr R6 (reg 22) = Z_to_bv 64 (F / 8 + 2147450880) -> getr R6 (reg 23) = Z_to_bv 64 F ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx6 R6 RA_ADB M6 model6) K.
