(* [comment removed for export] *)
Section Frame.
Variables (F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model).
Hypothesis G : PMAUK.gctx L ar HI LBX FF LK Aw sp SCR spc (sp - 104) sp OC OWN F fl 2 LK2 M2 model2 cr BX0.
Hypothesis APART : forall a n0 sp0 scr0, (forall i, 0 <= i < n0 -> aclient L ar (BX0 ++ LBX) FF sp0 scr0 (a + i)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes 2 <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes 2 / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a).
Local Notation FF' := ((F, 2, spc + 32) :: FF).
(* [comment removed for export] *)
Local Notation GM := (PQAKR3.g_mem L ar HI M model LBX FF LK Aw sp PQATSS.WRS_H W spc OWN 2 F).
Local Notation "'GF' f" := (f L ar C HI LY HIok K R M model LBX FF LK Aw cr sp r PQATSS.WRS_H BX0 W HH AM K0 ENT FRM FRS Hh2 wappW spc (sp - 104) sp OC OWN 2 F fl LK2 M2 model2 G APART HSPCf) (at level 10, f at level 9, only parsing).

(* [comment removed for export] *)
Definition vals (j : nat) : Z :=
  match j with 2%nat => spc | 3%nat => pa_gp AD | 4%nat => hl_tp L | 8%nat => sp | 9%nat => spc | 20%nat => ot | _ => 0 end.
Definition IXP : list nat := [2; 3; 4; 8; 9; 20]%nat.
Local Notation REGSP := (regl IXP vals).

(* [comment removed for export] *)
Ltac pf BIx :=
  destruct ((GF PQAKR3.g_pfacts) _ _ _ _ _ _ BIx) as ((PF1 & PF2 & PF3 & PF4 & _) & (FD & FW & FSW & FLU & FLW) & (PL1 & PL2 & PL3 & PL4) & (SW & OWNV & PS1 & PS2 & PS3 & PS4) & (CSB & CUAR & IMGC) & (AVSH & AVF & AVS));
  change (ff_bytes 2) with 256 in *; change (256 / 8) with 32 in *.

(* [comment removed for export] *)
Definition WPF (a : Z) : Prop := (sp - SCR <= a < sp) \/ (F <= a < F + 256) \/ (F / 8 + SB <= a < F / 8 + SB + 32).

(* [comment removed for export] *)
Lemma GEK BX1 M1 model1 LK1 Aw1 cr1 (M3 : mem) (Wp : Z -> Prop) :
  GM BX1 M1 model1 LK1 Aw1 cr1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) -> (forall a, Wp a -> WPF a) ->
