Lemma VRF_keep (Ma Mb : mem) fbq ql q0 q1 fbr rl r0 r1 :
  (forall a, F + 32 <= a < F + 128 -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) ->
  (forall a, F / 8 + SB <= a < F / 8 + SB + 32 -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) ->
  VRF Ma fbq ql q0 q1 fbr rl r0 r1 -> VRF Mb fbq ql q0 q1 fbr rl r0 r1.
Proof.
