Lemma L_DIV1 My modely LKy Awy cry (c p fbv : Z) (fx5 : FPState) R5 :
  GM [(p, c)] My modely LKy Awy cry -> vstr_at My ot (PM.VLong c 0 p) -> 32 <= c -> FRAM My -> VRF My fbv 2%nat v0 v1 0 0%nat 0 0 ->
  (forall n', PQATSW2.ws2_postL x (PM.VLong c n' p)) -> PMSP.credit_keep cr cry (POT x) (POT (PM.VLong c 0 p)) ->
  getr R5 (reg 1) = Z_to_bv 64 RA_DIV -> REGSP R5 ->
  getr R5 (reg 10) = Z_to_bv 64 (F + 32) -> getr R5 (reg 11) = Z_to_bv 64 (spc + 88) -> getr R5 (reg 12) = Z_to_bv 64 (F + 32) -> getr R5 (reg 13) = Z_to_bv 64 (F + 96) ->
  getr R5 (reg 14) = Z_to_bv 64 1 -> getr R5 (reg 18) = Z_to_bv 64 10 -> getr R5 (reg 21) = Z_to_bv 64 (F + 96) -> getr R5 (reg 22) = Z_to_bv 64 M10 ->
  getr R5 (reg 23) = Z_to_bv 64 (F + 104) -> getr R5 (reg 24) = Z_to_bv 64 (F + 32) -> getr R5 (reg 25) = Z_to_bv 64 18 ->
